final class Loop {
    var state: String
    var entity: Run
    var ports: [String: ([Any]) -> Void]
    private(set) var emitted: [(event: String, payload: any Encodable)] = []

    init(entity: Run, ports: [String: ([Any]) -> Void] = [:]) {
        self.state = "planning"
        self.entity = entity
        self.ports = ports
    }

    func emit(_ event: String, _ payload: any Encodable) {
        emitted.append((event: event, payload: payload))
    }

    func onInit() {
        if self.state == "planning" {
            self.state = "planning"
        } else if self.state == "acting" {
            self.state = "acting"
        } else if self.state == "done" {
            self.state = "done"
        }
    }

    func onToolChosen(_ payload: LoopTOOL_CHOSENPayload) {
        if self.state == "planning" && ((self.entity.steps ?? 0) < 5) {
            self.entity.steps = ((self.entity.steps ?? 0) + 1)
            self.emit("CALL_TOOL", LoopCALL_TOOLPayload(input: payload.input, name: payload.name))
            self.state = "acting"
        } else if self.state == "planning" && ((self.entity.steps ?? 0) >= 5) {
            self.entity.answer = "step budget reached"
            self.emit("ANSWERED", LoopANSWEREDPayload(answer: (self.entity.answer ?? "")))
            self.state = "done"
        }
    }

    func onFinal(_ payload: LoopFINALPayload) {
        if self.state == "planning" {
            self.entity.answer = payload.text
            self.emit("ANSWERED", LoopANSWEREDPayload(answer: (self.entity.answer ?? "")))
            self.state = "done"
        }
    }

    func onToolResult(_ payload: LoopTOOL_RESULTPayload) {
        if self.state == "acting" {
            self.entity.observations = ((self.entity.observations ?? []) + [payload.output])
            self.emit("OBSERVED", LoopOBSERVEDPayload(output: payload.output))
            self.state = "planning"
        }
    }
